*{box-sizing:border-box}body{margin:24px;color:#111;font:13px Arial,sans-serif}.toolbar{display:flex;justify-content:space-between;margin-bottom:18px}.toolbar a,.toolbar button{padding:9px 14px;background:#102d4f;color:white;border:0;text-decoration:none;cursor:pointer}.heading{text-align:center;margin-bottom:18px}.heading h1{font-size:18px;margin:5px 0;background:#000;color:#fff;padding:7px}.heading p{margin:3px}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0}.blank{display:inline-block;min-width:110px;border-bottom:1px solid #333;height:18px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #222;padding:7px 6px;text-align:left}th{background:#eee}.narrow{width:45px;text-align:center}.sign{width:120px;height:30px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:26px}.summary div{border-bottom:1px solid #222;padding:5px 0}@media print{body{margin:10mm}.toolbar{display:none}tr{break-inside:avoid}thead{display:table-header-group}}
